1	#!/usr/bin/env bash
2	# SUMMARY: cost-probe calibration adapter. install is a no-op; command returns a true(1) command with no env. Used by cost-guard smokes; produces no real model traffic.
3	set -euo pipefail
4	
5	usage() {
6	  cat >&2 <<'EOF'
7	Usage:
8	  cost-probe install <agent-artifact-path>
9	  cost-probe command  (reads profile JSON on stdin)
10	EOF
11	  return 2
12	}
13	
14	cmd_install() {
15	  local artifact="${1:-}"
16	  jq -cn \
17	    --arg src "$artifact" \
18	    '{install_command:"true", artifact_source:$src, binary_path:"", harbor_plugin:null}'
19	}
20	
21	cmd_command() {
22	  cat >/dev/null
23	  jq -cn '{command:["sh","-c","true"], env:{}, secret_env_keys:[]}'
24	}
25	
26	main() {
27	  local sub="${1:-}"
28	  case "$sub" in
29	    install) shift; cmd_install "$@";;
30	    command) shift; cmd_command;;
31	    -h|--help|"") usage;;
32	    *) echo "cost-probe: unknown subcommand: $sub" >&2; usage;;
33	  esac
34	}
35	
36	main "$@"
37

{
  "install_command": "true",
  "artifact_source": "/test-artifact",
  "binary_path": "",
  "harbor_plugin": null
}
